INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (13, 'Jahitan double chainstitch tidak terbentuk dengan benar', 'Jahitan rantai tidak terbentuk sempurna, mudah terurai, atau hasil jahitan tidak konsisten.', 'Pemasangan benang tidak benar, ketegangan benang tidak sesuai, atau posisi jarum dan looper kurang tepat.', 'Periksa kembali jalur benang, sesuaikan ketegangan benang, dan periksa posisi serta timing jarum dan looper.', 'Matikan mesin dan lepaskan sumber daya sebelum melakukan penyetelan pada area jarum atau looper.', 'Data spesifikasi JUKI MH-380 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (13, 'Benang jarum sering putus', 'Benang jarum putus berulang saat proses menjahit.', 'Jarum rusak atau tidak sesuai, jalur benang terhambat, tegangan benang terlalu tinggi, atau ada bagian yang kasar.', 'Ganti dengan jarum DP×17 yang sesuai, periksa jalur benang, kurangi ketegangan bila perlu, dan periksa bagian yang bersentuhan dengan benang.', 'Matikan mesin sebelum mengganti jarum atau memeriksa jalur benang.', 'Data spesifikasi JUKI MH-380 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (13, 'Benang looper sering putus', 'Benang pada looper sering putus atau rantai jahitan berhenti terbentuk.', 'Threading looper tidak benar, ketegangan terlalu tinggi, atau looper mengalami kontak yang tidak normal dengan jarum.', 'Periksa jalur benang looper, sesuaikan ketegangan, dan periksa posisi serta timing looper.', 'Matikan mesin sebelum membuka area looper atau melakukan penyetelan.', 'Data spesifikasi JUKI MH-380 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (13, 'Jahitan loncat atau rantai jahitan terlepas', 'Beberapa bagian jahitan tidak terbentuk dan rantai jahitan mudah terurai.', 'Jarum bengkok atau tumpul, timing jarum-looper tidak tepat, atau threading tidak sesuai.', 'Ganti jarum, periksa pemasangan dan timing jarum-looper, serta ulangi threading sesuai jalurnya.', 'Pastikan mesin berhenti total sebelum memeriksa jarum dan looper.', 'Data spesifikasi JUKI MH-380 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (13, 'Panjang jahitan tidak sesuai', 'Panjang stitch lebih pendek atau lebih panjang dari pengaturan.', 'Mekanisme drop feed kotor, pengaturan panjang jahitan berubah, atau feed tidak bekerja normal.', 'Periksa pengaturan panjang jahitan, bersihkan area feed, dan periksa mekanisme pemakanan kain.', 'Matikan mesin sebelum membersihkan atau memeriksa mekanisme feed.', 'Data spesifikasi JUKI MH-380 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (13, 'Kain tidak bergerak stabil saat dijahit', 'Kain bergerak tersendat, tertarik, atau panjang jahitan berubah selama proses.', 'Feed dog kotor atau aus, tekanan presser foot tidak sesuai, atau area feed mengalami gangguan.', 'Bersihkan feed dog, periksa tekanan presser foot, dan periksa kondisi mekanisme drop feed.', 'Matikan mesin sebelum membersihkan area feed atau melakukan penyetelan.', 'Data spesifikasi JUKI MH-380 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (13, 'Jarum patah atau posisi jarum tidak normal', 'Jarum patah, bengkok, atau posisi jarum tidak sesuai saat menjahit.', 'Jarum tidak sesuai, pemasangan kurang tepat, jarum membentur presser foot atau looper, atau timing tidak tepat.', 'Pasang jarum DP×17 yang sesuai dengan benar, periksa posisi jarum, dan periksa kemungkinan kontak dengan looper atau presser foot.', 'Matikan mesin dan lepaskan sumber daya sebelum mengganti jarum atau melakukan pemeriksaan.', 'Data spesifikasi JUKI MH-380 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (13, 'Pelumasan atau gerakan mesin tidak normal', 'Mesin terasa berat, menimbulkan suara tidak normal, atau gerakan mekanisme tidak lancar.', 'Pelumasan otomatis tidak bekerja dengan baik, level oli tidak sesuai, atau terdapat kotoran pada mekanisme.', 'Periksa sistem pelumasan otomatis, level oli sesuai prosedur mesin, dan bersihkan area mekanisme yang kotor.', 'Matikan mesin sebelum memeriksa sistem pelumasan atau bagian mekanis yang bergerak.', 'Data spesifikasi JUKI MH-380 dan panduan pemeriksaan umum');
